    [CascadingParameter] private HttpContext HttpContext { get; set; } = default!;
    [SupplyParameterFromForm] private LoginInput Input { get; set; } = new();
    [SupplyParameterFromQuery] private string? ReturnUrl { get; set; }

    private string? _error;

    private async Task DoLogin()
    {
        if (string.IsNullOrWhiteSpace(Input.Username) || string.IsNullOrWhiteSpace(Input.Password))
        {
            _error = "Vui lòng nhập đầy đủ tên đăng nhập và mật khẩu!";
            return;
        }

        await using var db = await DbFactory.CreateDbContextAsync();
        var username = Input.Username.Trim();
        var account = await db.Accounts.FirstOrDefaultAsync(a => a.Username == username);

        if (account == null || account.PasswordHash != Input.Password.Trim())
        {
            _error = "Tên đăng nhập hoặc mật khẩu không chính xác!";
            return;
        }
        if (!account.IsActive)
        {
            _error = "Tài khoản của bạn đã bị khóa! Vui lòng liên hệ quản trị viên.";
            return;
        }

        var claims = new List<Claim>
        {
            new(ClaimTypes.Name, account.Username),
            new(ClaimTypes.NameIdentifier, account.Id.ToString()),
            new(ClaimTypes.Role, account.Role)
        };
        var identity = new ClaimsIdentity(claims, CookieAuthenticationDefaults.AuthenticationScheme);
        await HttpContext.SignInAsync(CookieAuthenticationDefaults.AuthenticationScheme,
            new ClaimsPrincipal(identity),
            new AuthenticationProperties { IsPersistent = true, ExpiresUtc = DateTimeOffset.UtcNow.AddHours(8) });

        if (!string.IsNullOrEmpty(ReturnUrl) && ReturnUrl.StartsWith('/') && !ReturnUrl.StartsWith("//"))
            Nav.NavigateTo(ReturnUrl, forceLoad: true);
        else
            Nav.NavigateTo(account.Role == "Admin" ? "/admin/products" : "/", forceLoad: true);
    }

    private sealed class LoginInput
    {
        public string Username { get; set; } = "";
        public string Password { get; set; } = "";
    }

